   123	function useMedicationBaseline(
   124	  patientId: string | undefined,
   125	  encounterId: string | undefined,
   126	  facilityId: string | undefined,
   127	  prescriptionId: string | undefined,
   128	  currentUser: UserReadMinimal,
   129	): {
   130	  baseline: readonly BaselineRow<MedicationRequestRow>[] | undefined;
   131	  totalCount: number | undefined;
