   133	  const { data } = useQuery({
   134	    queryKey: ["medication_requests", patientId, encounterId, prescriptionId],
   135	    queryFn: query(medicationRequestApi.list, {
   136	      pathParams: { patientId: patientId! },
   137	      queryParams: {
   138	        encounter: encounterId,
   139	        prescription: prescriptionId,
   140	        ordering: "-modified_date",
   141	        limit: 100,
   142	        facility: facilityId,
   143	      },
   144	    }),
   145	    enabled: !!patientId && !!prescriptionId,
   146	  });
