  1	import type { QuestionnaireResponse } from "@/types/questionnaire/form";
  2	import type { StructuredEditRecord } from "@/types/questionnaire/structured";
  3	import { sanitizeStructuredEditLog } from "@/types/questionnaire/structured";
  4	
  5	import type {
  6	  StructuredBatchEntry,
  7	  StructuredRequestContext,
  8	} from "@/components/QuestionnaireV2/structured/types";
  9	
 10	/**
 11	 * Sanitized structured edit log: the user intent that compiles into requests
 12	 * and persists in drafts. Missing logs read as empty, malformed entries are
 13	 * dropped, and duplicate row edits collapse to the latest per row id.
 14	 */
 15	export function structuredEditsOf(
 16	  response: QuestionnaireResponse | undefined,
 17	): StructuredEditRecord[] {
 18	  return sanitizeStructuredEditLog(response?.edits);
 19	}
 20	
 21	/**
 22	 * Structural subset of a resolved structured type needed for v2 compile,
 23	 * kept registry-free so this module can run in plain tests.
 24	 */
 25	export interface StructuredV2Compiler {
 26	  toRequests: (
 27	    edits: readonly StructuredEditRecord[],
 28	    context: StructuredRequestContext,
 29	  ) => Promise<StructuredBatchEntry[]>;
 30	}
 31	
 32	/**
 33	 * Compile structured v2 edits into domain requests. Only clinician edits reach
 34	 * `toRequests`; untouched projected server rows produce no requests, and an
 35	 * empty log short-circuits before calling type code.
 36	 */
 37	export async function composeStructuredV2Requests(
 38	  definition: StructuredV2Compiler,
 39	  response: QuestionnaireResponse,
 40	  context: StructuredRequestContext,
 41	): Promise<StructuredBatchEntry[]> {
 42	  const edits = structuredEditsOf(response);
 43	  if (edits.length === 0) return [];
 44	  return definition.toRequests(edits, context);
 45	}
  1	import type { TFunction } from "i18next";
  2	
  3	import {
  4	  buildLinkIndex,
  5	  isQuestionEnabledInState,
  6	} from "@/components/QuestionnaireV2/form/engine/store";
  7	import {
  8	  resolveStructuredSlotState,
  9	  structuredDataAny,
 10	} from "@/components/QuestionnaireV2/structured/registry";
 11	
 12	import { structuredEditsOf } from "@/components/QuestionnaireV2/fill/submit/composeStructured";
 13	import type { RendererSubject } from "@/components/QuestionnaireV2/form/types";
 14	
 15	import type { QuestionValidationError } from "@/types/questionnaire/batch";
 16	import type { QuestionnaireResponse } from "@/types/questionnaire/form";
 17	import type { Question } from "@/types/questionnaire/question";
 18	import type { QuestionnaireRead } from "@/types/questionnaire/questionnaire";
 19	
 20	/**
 21	 * Submit-time structured validation. Enabled structured questions use the same
 22	 * slot-state resolver as the renderer; unavailable required sections block
 23	 * submit with a visible question error, while unavailable optional sections
 24	 * are skipped to match compose behavior. Ready sections run their type's
 25	 * validator and return finished message text.
 26	 */
 27	export function collectStructuredErrors(
 28	  questionnaire: QuestionnaireRead,
 29	  responses: Record<string, QuestionnaireResponse>,
 30	  subject: RendererSubject,
 31	  renderFailed: ReadonlySet<string>,
 32	  t: TFunction,
 33	): QuestionValidationError[] {
 34	  const linkIndex = buildLinkIndex(questionnaire.questions);
 35	  const errors: QuestionValidationError[] = [];
 36	
 37	  const walk = (list: Question[]) => {
 38	    for (const question of list) {
 39	      if (!isQuestionEnabledInState(question, responses, linkIndex)) continue;
 40	      if (question.type === "group") {
 41	        walk(question.questions ?? []);
 42	        continue;
 43	      }
 44	      if (question.type !== "structured" || !question.structured_type) {
 45	        continue;
 46	      }
 47	      const type = question.structured_type;
 48	      // The component threw (error boundary's own store) OR the resolver
 49	      // says anything but `ready` — unknown/disabled type, subject
 50	      // mismatch, missing context. Either way the slot shows a notice, not
 51	      // an input: a required question in this state hard-blocks, named; a
 52	      // non-required one is simply skipped, same as `composeBatch`. Skip
 53	      // resolving state at all once render already failed — there is
 54	      // nothing left to read a `ready` definition from.
 55	      const state = renderFailed.has(question.id)
 56	        ? undefined
 57	        : resolveStructuredSlotState(type, questionnaire.subject_type, subject);
 58	      if (!state || state.kind !== "ready") {
 59	        if (question.required) {
 60	          errors.push({
 61	            question_id: question.id,
 62	            error: t("structured_section_unavailable_required", {
 63	              label: question.text,
 64	            }),
 65	          });
 66	        }
 67	        continue;
 68	      }
 69	      const definition = state.definition;
 70	      if (!definition.validate) continue;
 71	      const response = responses[question.id];
 72	      // The recorded entries must belong to this question's type.
 73	      if (response?.structured_type !== type) continue;
 74	      const required = question.required ?? false;
 75	      const projection = structuredDataAny(response);
 76	      const edits = structuredEditsOf(response);
 77	      // Nothing recorded AND nothing changed. The two halves answer
 78	      // different questions, so neither may gate the other: a
 79	      // NON-empty projection with an empty log still runs (a required
 80	      // section satisfied by rows the server already had); a non-empty log
 81	      // with an empty projection still runs (the clinician removed every
 82	      // row).
 83	      if (projection.length === 0 && edits.length === 0) continue;
 84	      try {
 85	        errors.push(
 86	          ...definition.validate(projection, edits, question.id, required),
 87	        );
 88	      } catch (error) {
 89	        // Plugin code runs here. Contain throws as one question-scoped error
 90	        // the clinician can see and act on; the submit then aborts through
 91	        // the normal validation path instead of becoming a silent no-op.
 92	        console.error(
 93	          `Structured type "${type}" threw while validating question ${question.id}`,
 94	          error,
 95	        );
 96	        errors.push({
 97	          question_id: question.id,
 98	          error: t("structured_question_validate_failed"),
 99	        });
100	      }
101	    }
102	  };
103	  walk(questionnaire.questions);
104	  return errors;
105	}

