    28	/**
    29	 * Clears the question's render-failed mark when it mounts. Rendered INSIDE
    30	 * the error boundary, beside the structured component: if the component
    31	 * throws during the mounting render, the whole subtree — this probe
    32	 * included — is discarded before effects run, so the clear only ever fires
    33	 * for a commit whose input actually made it to the screen. That placement
    34	 * is what makes the mark track reality across an unmount/remount cycle
    35	 * (enable_when toggling the question): a recovered slot un-exempts itself,
    36	 * a still-broken one re-marks via the boundary's onError.
    37	 */
    38	function ClearRenderFailedOnMount({ questionId }: { questionId: string }) {
    39	  const clearRenderFailed = useClearStructuredRenderFailed(questionId);
    40	  useEffect(() => {
    41	    clearRenderFailed();
    42	  }, [clearRenderFailed]);
    43	  return null;
    44	}
    45	
    46	/**
    47	 * Renders core and plugin structured questions from a resolved definition.
    48	 * `onChange` is memoized for adapter callbacks, and preview withholds
    49	 * questionnaire ids so template CRUD stays off the builder surface.
    50	 */
    51	export function StructuredSlot({
    52	  question,
    53	  disabled,
    54	}: {
    55	  question: Question;
    56	  disabled: boolean;
    57	}) {
    58	  const { t } = useTranslation();
    59	  const { mode, subject, questionnaire } = useFormRenderer();
    60	  // Plugins register their types as their remote module loads, which can
    61	  // land after this slot first renders — subscribing re-resolves instead of
    62	  // leaving a permanent "requires a plugin" notice on screen.
    63	  useSyncExternalStore(
    64	    subscribeToStructuredTypes,
    65	    getStructuredTypesVersion,
    66	    getStructuredTypesVersion,
    67	  );
    68	  const [response, updateResponse] = useQuestionResponse(question.id);
    69	  const errors = useQuestionErrors(question.id);
    70	  const clearErrors = useClearQuestionErrors(question.id);
    71	  const markRenderFailed = useMarkStructuredRenderFailed(question.id);
    72	
    73	  const handleChange = useCallback(
    74	    (values: ResponseValue[], note?: string) =>
    75	      updateResponse({ values, note }),
    76	    [updateResponse],
    77	  );
    78	
    79	  // The same resolution submit-time enforcement runs — see
    80	  // `StructuredSlotState`'s parity note. Whatever this returns other than
    81	  // "ready" renders a notice, not an input: the question cannot be
    82	  // answered here, but a REQUIRED one still hard-blocks the submit by name
    83	  // (`collectStructuredErrors`) — this slot no longer waives it.
    84	  const state = question.structured_type
    85	    ? resolveStructuredSlotState(
    86	        question.structured_type,
    87	        questionnaire.subject_type,
    88	        subject,
    89	      )
    90	    : undefined;
    91	
    92	  // A type this deployment doesn't have (plugin disabled or removed after
    93	  // the questionnaire was authored) — say so instead of rendering nothing,
    94	  // which would read as an empty question. The notice's closing sentence
    95	  // must not contradict `collectStructuredErrors`' blocking error below
