    97	  // one says the opposite — the form can't be saved until this loads —
    98	  // so each notice key has a `_required` twin instead of one sentence
    99	  // trying to cover both outcomes.
   100	  if (state?.kind === "unknown_type") {
   101	    return (
   102	      <div className="rounded-lg border border-dashed border-amber-300 bg-amber-50 p-4 text-sm text-amber-800">
   103	        {t(
   104	          question.required
