   120	        {t(
   121	          question.required
   122	            ? "structured_type_subject_mismatch_required"
   123	            : "structured_type_subject_mismatch",
   124	          {
   125	            type: label,
   126	            // The raw enum reads as jargon in a clinician-facing notice;
   127	            // the studio's own subject picker labels these the same way.
   128	            subject: t(questionnaire.subject_type),
   129	          },
   130	        )}
   131	      </div>
   132	    );
   133	  }
   134	
   135	  if (state.kind === "missing_context") {
   136	    return (
   137	      <div className="rounded-lg border border-dashed border-gray-300 bg-gray-50 p-4 text-sm text-gray-500">
   138	        <p className="font-medium text-gray-700">{label}</p>
   139	        <p>
   140	          {t(
